// lib/canon/register.ts
//
// The canon register: every decision, rule, spec, research item, concept,
// conflict and open question from the twenty AIM-B5R studies (studies.ts),
// with the study and page it came from and where it lives in this repo.
//
// Status meanings
//   LOCKED    A rule the studies call canonical, locked, core or non-negotiable,
//             consistent with existing canon. Changing it needs the owner's
//             approval and a CANON_VERSION bump (see tests/canon.test.ts).
//   SPEC      Agreed shape of something to build later, behind its phase gate.
//   PROPOSED  A proposal awaiting the owner's decision.
//   RESEARCH  Kept as research; never an underwriting or product input.
//   CONCEPT   Fiction, brand or visual concept archive; never evidence.
//   OPEN      A decision only the owner can make.
//   CONFLICT  Two sources disagree; the owner must pick one.
//
// impl: built | partial | not_built | n/a (a rule with nothing to build) |
//       unchecked (not verified against the code in this pass).

import type { StudyId } from "./studies";

export type CanonStatus = "LOCKED" | "SPEC" | "PROPOSED" | "RESEARCH" | "CONCEPT" | "OPEN" | "CONFLICT";

export type CanonDomain =
  | "GOVERNANCE" | "PROPOPS8" | "AIM_B5R" | "INFRA" | "EDO_PATTERN" | "TRIADIC" | "ROBOTICS" | "MOBILITY"
  | "LET" | "DANCE8" | "STUTTR" | "STATE8" | "PLATE8" | "VISUAL" | "PURE" | "WARDROBE" | "WORLD";

export type Impl = "built" | "partial" | "not_built" | "n/a" | "unchecked";

export interface CanonSource {
  study: StudyId;
  page: number;
}

export interface CanonEntry {
  id: string;
  domain: CanonDomain;
  status: CanonStatus;
  statement: string;
  sources: CanonSource[];
  impl: Impl;
  /** Repo paths (or commits) that implement or hold this entry. */
  where?: string[];
  note?: string;
}

const s = (study: StudyId, ...pages: number[]): CanonSource[] => pages.map((page) => ({ study, page }));

